      // [CONFORMITE 2026] about
      abt_back_home: 'Accueil',
      abt_h1: 'À propos de Tabibi',
      abt_subtitle: 'La 1ère plateforme médicale 100% algérienne, conçue par et pour les Algériens.',
      abt_mission_title: 'Notre mission',
      abt_mission_p1: 'Tabibi a une seule ambition : <b>rendre l\'accès aux soins simple, rapide et transparent en Algérie</b>.',
      abt_mission_p2: 'Trop souvent, prendre rendez-vous chez un médecin demande des heures d\'attente au téléphone, des déplacements inutiles ou des recommandations informelles. Nous croyons qu\'à l\'ère du smartphone, ça ne devrait plus être le cas — surtout dans un pays comme l\'Algérie où plus de 35 millions de personnes ont besoin d\'un système de santé moderne.',
      abt_mission_p3: 'Notre plateforme connecte les <b>patients</b> aux <b>médecins certifiés</b> de toute l\'Algérie, en respectant les règles du Code de déontologie médicale et la loi 18-07 sur la protection des données.',
