      abt_back_home: 'Home',
      abt_h1: 'About Tabibi',
      abt_subtitle: 'The first 100% Algerian medical platform, built by and for Algerians.',
      abt_mission_title: 'Our mission',
      abt_mission_p1: 'Tabibi has a single ambition: <b>to make access to healthcare simple, fast and transparent in Algeria</b>.',
      abt_mission_p2: 'Too often, booking an appointment with a doctor means hours of waiting on the phone, unnecessary trips or informal recommendations. We believe that in the smartphone era, this should no longer be the case — especially in a country like Algeria where more than 35 million people need a modern healthcare system.',
      abt_mission_p3: 'Our platform connects <b>patients</b> with <b>certified doctors</b> across Algeria, in compliance with the Medical Code of Ethics and Law 18-07 on data protection.',
      abt_values_title: 'Our values',
      abt_val_privacy_t: 'Confidentiality',
      abt_val_privacy_d: 'Your medical data is encrypted (AES-256) and hosted in the EU. Never sold to third parties, ever.',
      abt_val_verified_t: 'Verified doctors',
      abt_val_verified_d: 'Every doctor on Tabibi is verified manually: diploma, Medical Council certificate, identity.',
      abt_val_dz_t: '100% Algerian 🇩🇿',
      abt_val_dz_d: 'Built in Algiers, compliant with Algerian law, with no foreign dependency for your sensitive data.',
      abt_val_free_t: 'Free for patients',
      abt_val_free_d: 'No fees, no hidden commission. Patients never pay Tabibi.',
      abt_val_nocommission_t: 'No doctor commission',
      abt_val_nocommission_d: 'In accordance with art. 17 of decree 92-276, Tabibi takes NO percentage of fees.',
